INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_0bf13effc6af969027706787","wiki/sources/ril-402-0203-inb-2027-data.md",3,"Seite 3","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 3\n\nNetzfahrplan\n\nBinnen eines Monats nach Fertig- Schriftliche Stellungnahmen der\n\nstellung des vorlÃ¤ufigen Anmelder zu Anmeldungen der ers-\n\nNetzfahrplanentwurfs ten Phase mÃ¶glich\n\nNach Bearbeitung der berechtig- EndgÃ¼ltiger Netzfahrplanentwurf\n\nten Beanstandungen (Frist wird zur ersten Phase der Netzfahrvon DB InfraGO festgelegt) planerstellung,\n\nAbgabe der Trassenangebote\n\nSpÃ¤testens fÃ¼nf Arbeitstage nach Annahme der\n\nEingang der Trassenangebote Trassenangebote\n\n* EndgÃ¼ltiger Netzfahrplanentwurf Erster Werktag der 11. Woche vor\n\n* zweite Phase der Netzfahrplaner- Fahrplanwechsel\n\nstellung\n\nErstellung der\n\nFahrplanunterlagen\n\nZweiter Samstag im Dezember, Wechsel des Netzfahrplans\n\n24:00 Uhr\n\n2 Planungsparameter\n\n(1) Die Planungsparameter umfassen fÃ¼r EVU/ZB und DB In- Inhalt\n\nfraGO AG relevante Aspekte fÃ¼r Fahrlagenplanung und\n\nTrassenkonstruktion.\n\n(2) Richtlinien, die die Fahrlagenplanung der EVU/ZB beein- Richtlinien\n\nflussen, mÃ¼ssen inhaltlich vor Beginn der Fahrlagenplanung bekannt sein.\n\n(3) Insbesondere folgende infrastrukturelle Rahmenbedingun- infrastrukturelle\n\ngen werden bekannt gegeben: Rahmenbedingungen\n\n- BauzuschlÃ¤ge (Beispiel siehe 402.0305A01),\n\n- Informationen zu der Netzfahrplanauswahl,\n\n- Verkehrsartenmixe fÃ¼r BaumaÃŸnahmen, die im Netzfahrplan bearbeitet werden (ab Netzfahrplan 2027\n\nentfallend),\n\n- VerÃ¤nderungen der Infrastruktur mit Auswirkungen\n\nauf den Fahrplan,\n\n- Ãœbergangszeiten in KnotenbahnhÃ¶fen (vgl. Anh. 1), 402.0203A01\n\n(4) Der Entwurf der Planungsparameter wird spÃ¤testens 17,5 Entwurf der Pla-\n\nMonate vor Fahrplanwechsel an die Kunden der DB Infra- nungsparameter\n\nGO AG versendet. Ãœbrige EVU bzw. die ZB erhalten die",214,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":3,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","9a0fb857202f942d8e22904678ed402104accac9ded45dbeb7a475d1b21695cd"],["chunk_9d289cb2bec53dba7d1bae7f","wiki/sources/ril-402-0203-inb-2027-data.md",4,"Seite 3","GÃ¼ltig ab 13.12.2026",3,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":3,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","051caa96f9d63b3eebe92b62adccbc3831be5b0475d9b0fcff6df00d65a1fc7f"],["chunk_672c64f18579bbae8ac657e9","wiki/sources/ril-402-0203-inb-2027-data.md",5,"Seite 4","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 4\n\nNetzfahrplan\n\nUnterlagen auf Anfrage. Die EVU/ZB haben 15 Arbeitstage\n\nGelegenheit zur schriftlichen Stellungnahme. Die DB Infra-\n\nGO AG hat die Stellungnahmen zu prÃ¼fen und ggf. in den\n\nPlanungen zu berÃ¼cksichtigen, soweit die jeweiligen infrastrukturellen, betrieblichen und/oder technischen Gegebenheiten dies zulassen.\n\nAbgestimmte (5) SpÃ¤testens 16 Monate vor Fahrplanwechsel teilt die DB\n\nPlanungspara- InfraGO AG ihren Kunden bzw. den Ã¼brigen\n\nmeter EVU/ZB die abgestimmten Planungsparameter mit.\n\nAktualisierung (6) Die aktualisierten Planungsparameter gibt die DB InfraGO\n\nAG spÃ¤testens 13 Monate vor dem Netzfahrplanwechsel\n\nbekannt.\n\nDie EVU/ZB haben zehn Arbeitstage Gelegenheit zur\n\nschriftlichen Stellungnahme.\n\nDie DB InfraGO AG hat diese Stellungnahmen zu prÃ¼fen\n\nund ggf. noch in den Planungen zu berÃ¼cksichtigen, soweit\n\ndie jeweiligen infrastrukturellen, betrieblichen und/oder\n\ntechnischen Gegebenheiten dies zulassen.\n\nEndgÃ¼ltige Pla- (7) SpÃ¤testens 12 Monate vor Fahrplanwechsel teilt die DB\n\nnungsparameter InfraGO AG ihren Kunden bzw. den Ã¼brigen\n\nEVU/ZB die endgÃ¼ltigen Planungsparameter mit.\n\n3 Fahrlagenberatung\n\nFahrlagen- (1) Die DB InfraGO AG berÃ¤t alle EVU/ZB auf Wunsch im\n\nberatung Rahmen der Fahrlagenplanungen. Auf Basis der vorhandenen Daten wird die Machbarkeit der Konzepte bzw. Fahrlagen unverbindlich geprÃ¼ft.\n\n4 Bearbeitung Trassenanmeldung\n\nPrÃ¼fung der (1) Die fÃ¼r die Bearbeitung der Trasse zustÃ¤ndige Stelle der\n\nTrassen- DB InfraGO AG prÃ¼ft die Trassenanmeldung auf VollstÃ¤nanmeldung digkeit und PlausibilitÃ¤t.\n\nFehlende oder (2) EnthÃ¤lt die Trassenanmeldung fehlende, nicht plausible",222,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":4,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","aa869aea4f43f997441c3ae9928362994a2dc4149859f00d0b31adf7467c90a0"],["chunk_081306d9aa2d4586a7b5bc9b","wiki/sources/ril-402-0203-inb-2027-data.md",6,"Seite 4","nicht plausible oder widersprÃ¼chliche Angaben, so fordert die DB InfraGO\n\nAngaben AG gemÃ¤ÃŸ Ziffer 4.2.1.1 der INB die jeweiligen Angaben\n\nbeim EVU/ZB unverzÃ¼glich in Schriftform nach.\n\nNach Ablauf der Anmeldefrist gemÃ¤ÃŸ Ziffer 4.2.1.3 der INB\n\nhat das EVU/der ZB die Angaben nach Aufforderung innerhalb von 3 Arbeitstagen zu Ã¼bermitteln.\n\nGÃ¼ltig ab 13.12.2026",52,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":4,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","0bbf8645c9451510bbc502dbcb243b39cd1d0a9f69aef916530bcbc8d5f14ba8"],["chunk_d21abf0e17591c9fc9a640ce","wiki/sources/ril-402-0203-inb-2027-data.md",7,"Seite 5","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 5\n\nNetzfahrplan\n\nDie Nachforderung sowie die Antwort des EVU/ZB sind zu Dokumentation\n\ndokumentieren.\n\nÃœbermitteln EVU/ZB die Angaben erst nach Ablauf dieser\n\nFrist, so wird die Anmeldung zurÃ¼ckgewiesen.\n\n(3) Fehlende, nicht plausible oder widersprÃ¼chliche Angaben Fehlende, nicht\n\nliegen immer dann vor, wenn die Trassenanmeldung auf- plausible oder\n\ngrund der vom EVU/ZB angemeldeten betrieblich- widersprÃ¼chliche Angaben\n\ntechnischen Parameter nicht oder nur unvollstÃ¤ndig bearbeitet werden kann. Nicht plausible Angaben liegen z. B.\n\nvor, wenn die Trassenanmeldung der in den INB kommunizierten Beschreibung der Infrastruktur widerspricht (z. B.\n\nein Zug mit elektrischer Traktion soll Ã¼ber eine nicht\n\nelektrifizierte Strecke verkehren).\n\n5 Trassenkonstruktion\n\n(1) Alle fristgerecht vorliegenden Trassenanmeldungen sind Grundsatz\n\nwÃ¤hrend des gesamten Prozesses der Trassenbearbeitung\n\ndiskriminierungsfrei zu behandeln.\n\nDie Trassen werden unter BerÃ¼cksichtigung der WÃ¼nsche\n\nder EVU/ZB nach den MaÃŸgaben des betrieblichtechnischen Regelwerks konstruiert.\n\n(2) Wird bei einer grenzÃ¼berschreitenden Trassenanmeldung VorlÃ¤ufige\n\nauf die gemÃ¤ÃŸ Â§ 47 Abs. 7 ERegG vorlÃ¤ufigen grenzÃ¼ber- grenzÃ¼berschreitenden Zugtrassen Bezug genommen und kommt in schreitende Zugtrassen\n\nKoordinierungsverfahren keine Einigung zu Stande, so findet fÃ¼r diese Trassenanmeldung das Streitbeilegungsverfahren keine Anwendung.\n\nLiegen mehr als eine grenzÃ¼berschreitende Trassenanmeldung fÃ¼r die gleiche gemÃ¤ÃŸ Â§ 47 Abs. 7 ERegG vorlÃ¤ufige\n\ngrenzÃ¼berschreitende Zugtrasse vor, und kommt im Koordinierungsverfahren keine Einigung zu Stande, so findet\n\nfÃ¼r diese Trassenanmeldungen das Verfahren nach",217,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":5,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","66a09ff335cac3c1e582a36543dfc668ab09734db2240b4c05ce8afa9a2d5c57"],["chunk_4c40a2f681de732224238c23","wiki/sources/ril-402-0203-inb-2027-data.md",8,"Seite 5","Abschnitt 7 und ggf. nach Abschnitt 8 statt.\n\n(3) Ziel der Trassenkonstruktion ist es, allen AntrÃ¤gen auf Zu- Ziel der\n\nweisungen von Zugtrassen so weit wie mÃ¶glich stattzuge- Konstruktion\n\nben bei gleichzeitig bestmÃ¶glicher Ausnutzung der verfÃ¼gbaren InfrastrukturkapazitÃ¤t.\n\n(4) Die Konstruktion der fÃ¼r einen Konstruktionsabschnitt Reihenfolge der\n\nvorliegenden Trassenanmeldungen beginnt in der Regel Bearbeitung\n\nmit der Trasse, die den Konstruktionsraum ab 0:00 Uhr als\n\nGÃ¼ltig ab 13.12.2026",66,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":5,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","4b2da4bc722701e8b21408af33989406f60a5214d9143e238ac09d6880b71c70"],["chunk_772a2cee1b7ff83f0d194d89","wiki/sources/ril-402-0203-inb-2027-data.md",9,"Seite 6","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 6\n\nNetzfahrplan\n\nerstes berÃ¼hrt. Alle weiteren Trassenanmeldungen werden\n\nentsprechend ihrer zeitlichen Lage nacheinander bearbeitet.\n\nSofern eine andere Bearbeitungsreihenfolge zweckmÃ¤ÃŸiger\n\nerscheint (z.B. zunÃ¤chst Bearbeitung der Trassen, die in\n\ndie HVZ fallen), kann auch diese gewÃ¤hlt werden.\n\nInfrastruktur- (5) An Schnittstellen mit anderen Infrastrukturbetreibern oder\n\nschnittstellen auslÃ¤ndischen Bahnen ist die fahrplantechnische Machbarkeit nach den Regeln des jeweiligen Infrastrukturbetreibers sicherzustellen. Soweit erforderlich sind schriftliche\n\nProtokolle zu erstellen.\n\nErfahrungen aus (6) Durch Informationsaustausch zwischen Betrieb, Fahrplan\n\ndem laufenden und EVU/ZB sind stÃ¤ndig wiederkehrende VerspÃ¤tungen\n\nFahrplan und deren Ursachen zu identifizieren. Wenn diese durch\n\nModifikationen im Fahrplan reduziert werden kÃ¶nnen, sollten diese in die Netzfahrplanerstellung einflieÃŸen.\n\nKonstruktions- (7) Das Trassenangebot soll der Trassenanmeldung entsprespielrÃ¤ume chen. Ist dies wegen konkurrierender Trassenanmeldungen\n\nnicht mÃ¶glich, gilt Folgendes:\n\nSoweit nicht im SPFV die Marktsegmente Punkt-zu-Punkt\n\nund Nacht (vgl. 5.3.2 der INB) oder im SGV Marktsegmente mit den ZusÃ¤tzen â€žZ-Flexâ€œ oder â€žR-Flexâ€œ (vgl. 5.3.4 der\n\nINB) bestellt werden, versucht die DB InfraGO AG innerhalb folgender SpielrÃ¤ume ein Trassenangebot zu erstellen\n\n- Schienenpersonenverkehr +/- 3 Minuten,\n\n- Ãœbrige Zugtrassen (z.B. GÃ¼terzÃ¼ge, Triebfahrzeugfahrten): +/- 30 Minuten.\n\nFÃ¼r die Marktsegmente Nacht (nur bei Anwendung auf\n\ndem Gesamtlaufweg) und Punkt-zu-Punkt im SPFV gilt ein\n\nKonstruktionsspielraum von +/- 30 Minuten, fÃ¼r die",209,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":6,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","93d18dd20922e3397a86de578ceab3908a33678cbe29c16563103fc33e6fe8fa"],["chunk_390467d5e8607a7e47a72f31","wiki/sources/ril-402-0203-inb-2027-data.md",10,"Seite 6","Marktsegmente mit den ZusÃ¤tzen Z-Flex und R-Flex ein\n\nKonstruktionsspielraum von +/- 120 Minuten.\n\nDies erfolgt ohne RÃ¼cksprache mit dem Antragsteller.\n\nTrassenverknÃ¼p- (8) Werden durch Anwendung der o.g. KonstruktionsspielrÃ¤ufungen/ An- me WÃ¼nsche der EVU/ZB zur Anschlussbinschlussbindun- dung/TrassenverknÃ¼pfung nicht erfÃ¼llt, wird hier auch das\n\ngen\n\nKoordinierungsverfahren nach Abschnitt 6 eingeleitet.\n\nGÃ¼ltig ab 13.12.2026",51,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":6,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","51e6cb4e7841d01e519ed262122fed6e52712cd61e70557b2865f778b42a66c3"],["chunk_6f7606be9bb55c4fac26e644","wiki/sources/ril-402-0203-inb-2027-data.md",11,"Seite 7","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 7\n\nNetzfahrplan\n\n6 Trassenkonflikt und Koordinierungsverfahren\n\n(1) Ein Trassenkonflikt liegt vor, wenn auch nach Ausnutzung Konfliktder KonstruktionsspielrÃ¤ume nach Abschnitt 5 (7) weiter- definition\n\nhin AntrÃ¤ge Ã¼ber zeitgleiche/nicht zu vereinbarende Zuweisungen vorliegen.\n\nTrassenkonflikte entstehen insbesondere\n\nâ€“ durch Ãœberlagerung von Sperrzeitentreppen,\n\nâ€“ durch Nichteinhaltung der verbindlichen Pufferzeiten\n\nzwischen den Sperrzeitentreppen gemÃ¤ÃŸ\n\n402.0203A02,\n\nâ€“ Ãœberlagerung von Gleisbelegungen in Knoten,\n\nâ€“ Begegnungsverbote zwischen bestimmten Zugarten\n\nund\n\nâ€“ durch besondere Bedingungen bei der BefÃ¶rderung\n\nvon auÃŸergewÃ¶hnlichen Transporten oder Gefahrgut.\n\n(2) Erkennt der Konstrukteur, dass die Trassenbearbeitung Einleitung Koornach AusschÃ¶pfung der KonstruktionsspielrÃ¤ume nicht dinierungsverkonfliktfrei mÃ¶glich ist, leitet er das Koordinierungsverfah- fahren\n\nren ein.\n\n(3) Der fÃ¼r das einzuleitende Koordinierungsverfahren maÃŸ- Konfliktidentifigebliche Konflikt (PrimÃ¤rkonflikt) ergibt sich aus dem kation PrimÃ¤r-\n\nLaufweg der beteiligten Trassen in Verbindung mit der von konflikt\n\nden Trassenanmeldern gewÃ¼nschten Bearbeitungsrichtung\n\n(VorwÃ¤rts- oder RÃ¼ckwÃ¤rtsbearbeitung). Es handelt sich\n\nhierbei um den ersten unter diesen Bedingungen auftretenden Konflikt. Unterscheiden sich die Bearbeitungsrichtungen innerhalb einer Trassenanmeldung durch die Angabe eines Fixpunktes fÃ¼r die Konstruktion, ergeben sich\n\n* dadurch unterschiedliche Laufwegsabschnitte. In der Tras-\n\n* senanmeldung darf pro zeitlich getrennter Zeitscheibe ma-\n\n* ximal ein Fixpunkt angegeben werden, andernfalls wird die\n\n* Trassenanmeldung als nicht plausibel i.S.d. Ziffer 4.2.1.1",203,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":7,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","f6273f84ee36ccdb4db44c74eec302247bfe472735d0add7ce3c216c06dc73d9"],["chunk_480f86ca9177b2a04c0728c9","wiki/sources/ril-402-0203-inb-2027-data.md",12,"Seite 7","* behandelt. Die Reihenfolge der Konfliktbearbeitung erfolgt\n\naus der Reihenfolge der Laufwegsabschnitte. Als erstes erfolgt die Konstruktion entgegen der Laufrichtung. Erfolgt\n\nkeine Angabe eines Fixpunktes erfolgt die Trassenkonstruktion in Laufrichtung. Bei der Konfliktidentifikation ist\n\ndie Gleisbelegung (Strecke und Knoten) des Netzfahrplans\n\nGÃ¼ltig ab 13.12.2026",44,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":7,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","46a7e92d15f8b465bdc31a1676d20743ef583327a6677f68110945d464d7669e"],["chunk_7121a57fffea9a0870126b61","wiki/sources/ril-402-0203-inb-2027-data.md",13,"Seite 8","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 8\n\nNetzfahrplan\n\nmaÃŸgeblich. Ein PrimÃ¤rkonflikt in der Gleisbelegung wird *\n\ndurch die Trassenanmeldung definiert, die im Rahmen des *\n\nBearbeitungsfortschritts der Netzfahrplanerstellung nicht *\n\nmehr konfliktfrei konstruiert werden kann. Der Konflikt *\n\numfasst rÃ¤umlich alle Gleise die betrieblich und technisch *\n\n(z.B. aufgrund der vorhandenen Fahrwege, der GleislÃ¤nge *\n\noder der Elektrifizierung) fÃ¼r diese Trassenanmeldung ge- *\n\neignet sind und zeitlich die Belegung eines solchen Gleises *\n\ndurch die Trassenanmeldung, die im Rahmen des Bearbei- *\n\ntungsfortschritts der Netzfahrplanerstellung nicht mehr *\n\nkonfliktfrei konstruiert werden kann, einschlieÃŸlich des *\n\nKonstruktionsspielraums nach Ziffer 4.2.1.6 der INB. *\n\nGrundsÃ¤tze des (4) FÃ¼r das durchzufÃ¼hrende Koordinierungsverfahren gelten\n\nKoordinierungs- folgende GrundsÃ¤tze:\n\nverfahrens\n\n- Die Zugangsberechtigten, deren Trassenanmeldungen\n\nkonfligieren, werden unverzÃ¼glich und gleichzeitig\n\n(z.B. per E-Mail) Ã¼ber den bestehenden Konflikt informiert,\n\n- Das Koordinierungsverfahren erfordert einen straffen\n\nZeitplan zur KonfliktlÃ¶sung,\n\n- WÃ¤hrend der Koordinierung ruht die Trassenkonstruktion fÃ¼r die konfliktbeteiligten Trassen,\n\n- Die DB InfraGO AG wirkt durch Verhandlungen auf\n\neinvernehmliche LÃ¶sungen hin, wobei sie eigene VorschlÃ¤ge unterbreitet. Diese kÃ¶nnen auch in zeitlicher\n\nund rÃ¤umlicher Lage von der Trassenanmeldung abweichen,\n\n- Die Zugangsberechtigten kÃ¶nnen eigene LÃ¶sungsvorschlÃ¤ge einbringen, die durch die DB InfraGO AG auf\n\nRealisierbarkeit geprÃ¼ft werden,\n\n- VorschlÃ¤ge fÃ¼r die KonfliktlÃ¶sung werden nur umgesetzt, sofern der Konflikt dadurch fÃ¼r alle Beteiligten\n\ngelÃ¶st wird,",221,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":8,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","67ac5d4b4c37d3e02668216e72494e927acb198e1ba80bec71e1a0f998e54221"],["chunk_0d8fb8ad374ed1fb6b1dc241","wiki/sources/ril-402-0203-inb-2027-data.md",14,"Seite 8","- Bei komplexen Sachverhalten werden durch die DB\n\nInfraGO AG GesprÃ¤che entweder als Telefon- oder als\n\nPrÃ¤senzkonferenzen organisiert,\n\n- Wird im Koordinierungsverfahren eine einvernehmliche LÃ¶sung gefunden, so wird diese unverzÃ¼glich\n\ndurch die DB InfraGO AG dokumentiert und bildet die\n\nBasis fÃ¼r die weitere Erarbeitung des VNP. Diese Ver-\n\nGÃ¼ltig ab 13.12.2026",51,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":8,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","e14eb2f88d044c613049588fe4f6f00606fc3b37883b9efaf69f333fa1fc477f"],["chunk_64b074c85f84803915d56a93","wiki/sources/ril-402-0203-inb-2027-data.md",15,"Seite 9","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 9\n\nNetzfahrplan\n\neinbarungen sind verbindlich und kÃ¶nnen im Rahmen\n\ndes Koordinierungsverfahrens nicht mehr nachtrÃ¤glich aufgehoben oder verÃ¤ndert werden,\n\n- Wird im Koordinierungsverfahren eine einvernehmliche LÃ¶sung gefunden und entsteht fÃ¼r eine der beteiligten Trassen im weiteren Konstruktionsverlauf ein\n\nneuer Konflikt, so ist dies ein neuer PrimÃ¤rkonflikt.\n\nIst eine LÃ¶sung dieses neuen Konfliktes nicht mÃ¶glich,\n\nso erfolgt fÃ¼r diesen neuen Konflikt die Einleitung des\n\nStreitbeilegungsverfahrens nach Abschnitt 7 oder die\n\nâ€“ sofern erforderlich - Einleitung des HÃ¶chstpreisverfahrens nach Abschnitt 8. Eine RÃ¼ckkehr zu bereits\n\ngelÃ¶sten PrimÃ¤rkonflikten ist ausgeschlossen.\n\n(5) Im Rahmen der vereinfachten Koordinierung kann der Vereinfachte\n\nKonstrukteur mit einem LÃ¶sungsvorschlag zuerst auf das Koordinierung\n\nEVU/den ZB per Mail oder telefonisch zugehen, bei dem\n\ndie geringsten Abweichungen/Folgen gegenÃ¼ber den Trassenanmeldungen vorliegen.\n\nIn diesen FÃ¤llen erfolgt die Information Ã¼ber den Konflikt\n\nin anonymer Form. Sie beinhaltet Angaben zur zeitlichen\n\nLage und zum Ort des Konflikts, und die Angabe, welcher\n\nVerkehrsart (SPFV, SPNV, SGV) die Trasse des konfliktbeteiligten ZB zugeordnet ist, nicht jedoch Angaben Ã¼ber die\n\nkonfliktbeteiligten ZB.\n\nFÃ¼hrt die vereinfachte Koordinierung nicht zur LÃ¶sung,\n\nkann die DB InfraGO AG auf weitere Konfliktpartner zugehen.\n\nWurde eine einvernehmliche LÃ¶sung gefunden, so wird\n\ndiese unverzÃ¼glich durch die DB InfraGO AG dokumentiert\n\n(z.B. per Mail oder Bestelltool) und an das EVU/den ZB\n\nÃ¼bermittelt. Diese einvernehmliche LÃ¶sung bildet die Basis\n\nfÃ¼r die weitere Erarbeitung des VNP.",230,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":9,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","070e4056b63273527a14b5d078c1d7b8ab5c1419c5e6506cf41d8b0491c72301"],["chunk_dedce27b22fafb216d519c36","wiki/sources/ril-402-0203-inb-2027-data.md",16,"Seite 9","FÃ¼hrt die Vorgehensweise der vereinfachten Koordinierungen zu keinem Ergebnis, wird die komplexe Koordinierung mit KonfliktlÃ¶sungsgesprÃ¤ch mit allen Beteiligten eingeleitet.\n\n(6) Wenn die Koordinierung nach (5) erfolglos blieb, leitet die Koordination bei\n\nDB InfraGO AG unmittelbar das KonfliktlÃ¶sungsgesprÃ¤ch komplexen Verein. Dies erfolgt grundsÃ¤tzlich in Form einer Telefonkonfe- hÃ¤ltnissen\n\nrenz mit allen Beteiligten, in deutscher Sprache und nach\n\nfolgender Struktur:\n\nGÃ¼ltig ab 13.12.2026",61,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":9,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","cb1e9760bcff380f0939b19c67a99f33633bcc1e7ecfcde7e5f3f7b55e26850a"],["chunk_8062e5f220d3f8856147b929","wiki/sources/ril-402-0203-inb-2027-data.md",17,"Seite 10","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 10\n\nNetzfahrplan\n\n- Einladung durch die DB InfraGO AG,\n\n- Zustimmung aller Beteiligter zur Offenlegung der Angaben zu den betroffenen Trassen innerhalb eines\n\nArbeitstages (ansonsten EinzelgesprÃ¤che mit jedem\n\nEVU/ZB),\n\n- Konkrete Vorstellung des Konflikts und der Konfliktbeteiligten,\n\n- Unterbreitung von LÃ¶sungsvorschlÃ¤gen durch die DB\n\nInfraGO AG,\n\n- Ggf. Unterbreitung von LÃ¶sungsvorschlÃ¤gen durch\n\nEVU/ZB.\n\nDie DB InfraGO AG prÃ¼ft Alternativen zur Trassenanmeldung und bringt LÃ¶sungsvorschlÃ¤ge ein, die grundsÃ¤tzlich\n\nin einem\n\n- zeitlichen Rahmen von\n\n+/- 1 Stunde beim SPV und\n\n+/- 2 Stunden beim SGV, sowie einem\n\n- rÃ¤umlichen Rahmen, der sich an der Anmeldung orientiert (z. B. an Kundenhalten)\n\nliegen.\n\nLÃ¶sungsvorschlÃ¤ge der EVU/ZB erfordern den Bezug zur\n\nangemeldeten Trasse. Wird hiervon durch das EVU/ZB abgewichen, ist eine Vereinbarung des EVU/ZB mit der DB\n\nInfraGO AG Ã¼ber die zu prÃ¼fenden Alternativlaufwege erforderlich.\n\nAufgrund des engen Zeitrahmens zur Netzfahrplanerstellung kÃ¶nnen grundsÃ¤tzlich zwei Alternativlaufwege durch\n\ndie DB InfraGO AG geprÃ¼ft werden.\n\nDie Telefonkonferenzen oder GesprÃ¤che werden durch die\n\nDB InfraGO AG dokumentiert. Die Dokumentation enthÃ¤lt\n\ndabei mind. Angaben zu den betroffenen EVU/ZB, den betroffenen Trassen, den diskutierten LÃ¶sungsvorschlÃ¤gen\n\nund das Ergebnis des GesprÃ¤chs.\n\nWurde eine einvernehmliche LÃ¶sung gefunden, so bildet\n\ndiese die Basis fÃ¼r die weitere Erarbeitung des VNP.\n\nZu jedem Konflikt werden maximal zwei GesprÃ¤che gefÃ¼hrt, wobei das zweite GesprÃ¤ch nur dann durchgefÃ¼hrt\n\nGÃ¼ltig ab 13.12.2026",226,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":10,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","2382ba27e32adc34235322800620a2e0ea9d125392fdccdb811d47a68e6a196a"],["chunk_e681ed53c7691ee16edbc649","wiki/sources/ril-402-0203-inb-2027-data.md",18,"Seite 11","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 11\n\nNetzfahrplan\n\nwird, wenn sich alle Beteiligten dafÃ¼r aussprechen und den\n\nerfolgreichen Abschluss der Koordinierung damit fÃ¼r mÃ¶glich halten.\n\n(7) Die EVU/ZB haben einen Arbeitstag Zeit, die erarbeiteten Zustimmung zum\n\nErgebnisse der GesprÃ¤che zu bestÃ¤tigen. Die DB InfraGO Koordinierungs-\n\nAG fordert dabei die EVU/ZB auf, ggf. zu belegen, ob es ergebnis\n\nsich bei der konfliktbehafteten Anmeldung um einen vertakteten oder ins Netz eingebundenen Verkehr handelt\n\n(vgl. Abschnitt 3). Erfolgt in der Frist gemÃ¤ÃŸ Ziffer 4.2.1.9\n\nb) Satz 4 in Verbindung mit Ziffer 4.2.1.1 der NBN kein\n\nderartiger Nachweis, kann bei einer ggf. erforderlichen\n\nEntscheidung nach Â§ 52 Abs. 7 Nr. 1 ERegG das Kriterium\n\nâ€žvertakteter oder ins Netz eingebundener Verkehrâ€œ nicht\n\nherangezogen werden.\n\n(8) Erkennt die DB InfraGO AG, dass die LÃ¶sung eines Kon- PrimÃ¤r- und\n\nflikts (PrimÃ¤rkonflikt) einen Folgekonflikt (SekundÃ¤rkon- SekundÃ¤rflikt) auslÃ¶st, so ist fÃ¼r den SekundÃ¤rkonflikt auch das Ko- konflikt\n\nordinierungsverfahren durchzufÃ¼hren Dazu werden zunÃ¤chst die KonstruktionsspielrÃ¤ume der einbezogenen weiteren Trasse genutzt. Sollten diese nicht ausreichen, wird\n\nversucht, vom betroffenen EVU/ZB grÃ¶ÃŸere SpielrÃ¤ume fÃ¼r\n\ndiese Trasse zu erhalten. FÃ¼hrt das Koordinierungsverfahren fÃ¼r den SekundÃ¤rkonflikt zu keiner einvernehmlichen\n\nLÃ¶sung, so gilt der SekundÃ¤rkonflikt als unlÃ¶sbar und der\n\nPrimÃ¤rkonflikt ist wieder maÃŸgebend.\n\nFÃ¼r den PrimÃ¤rkonflikt ist dann eine andere LÃ¶sung zu suchen oder das Streitbeilegungsverfahren einzuleiten.\n\n(9) Abweichungen von den oben beschriebenen Verfahren im Baubedingt ein-\n\nFalle baubedingt eingeschrÃ¤nkter Infrastruktur werden geschrÃ¤nkte",234,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":11,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","85e778c86660b5cb68ff4ef06dcb715ea492731c03e5c3e8cfa4a622358f6b9a"],["chunk_1a91cfd8ab45f645189537e0","wiki/sources/ril-402-0203-inb-2027-data.md",19,"Seite 11","zur-zeit erarbeitet und nach Fertigstellung in das Modul Infrastruktur\n\n402.0305 eingestellt.\n\n(10) Auf die DurchfÃ¼hrung eines Koordinierungsverfahrens Verzicht auf das\n\nnach Abschnitt 6 kann verzichtet werden, sofern fÃ¼r ein Koordinierungsund denselben Auftrag eines Dritten (z.B. Ausschreibung) verfahren\n\nrÃ¤umlich und zeitlich dicht beieinander liegende oder identische Trassenanmeldungen mehrerer ZB vorliegen und\n\nsÃ¤mtliche ZB ihr EinverstÃ¤ndnis erklÃ¤rt haben.\n\nUnter diesen Voraussetzungen Ã¼bermittelt die DB InfraGO\n\nAG sÃ¤mtlichen beteiligten ZB den vorlÃ¤ufigen und endgÃ¼ltigen Netzfahrplanentwurf. Die jeweiligen Trassenangebote werden auflÃ¶send bedingt im Hinblick auf die Auf-\n\nGÃ¼ltig ab 13.12.2026",86,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":11,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","9e7c7ecc25dfa1643d7549d92bae235233f336d0df6a6a4b46379bb67add66fc"],["chunk_a305140cdd37f4aa9c83a714","wiki/sources/ril-402-0203-inb-2027-data.md",20,"Seite 12","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 12\n\nNetzfahrplan\n\ntragserteilung. Die DB InfraGO AG ist unverzÃ¼glich nach\n\nAuftragserteilung durch die beteiligten ZB zu informieren.\n\n7 Streitbeilegungsverfahren\n\nStreitbeile- (1) FÃ¼hrt das in Abschnitt 6 genannte Koordinierungsverfahgungsverfahren ren zu keiner einvernehmlichen LÃ¶sung, wird das Streitbeieinleiten legungsverfahren eingeleitet. FÃ¼r Trassen, die im Streitbeilegungsverfahren obsiegen, ist nur eine Stornierung im\n\nSinne von Ziffer 5.6.4.3 mÃ¶glich. Ziffer 5.6.4 findet keine\n\nAnwendung.\n\nVorrangregeln (2) Die Entscheidung im Streitbeilegungsverfahren erfolgt zu- *\n\nnÃ¤chst nach den Vorrangregeln gemÃ¤ÃŸ Ziffer 4.2.1.9 der *\n\nINB. *\n\nRegelentgelt- (3) Ergibt sich nach den Vorrangregeln gemÃ¤ÃŸ Absatz 2 wei- *\n\nverfahren terhin eine Gleichrangigkeit, erfolgt die Entscheidung im *\n\nRegelentgeltverfahren gemÃ¤ÃŸ Ziffer 4.2.1.10 der INB. *\n\n*\n\n8 HÃ¶chstpreisverfahren\n\nHÃ¶chstpreis- (1) FÃ¼hrt das Regelentgeltverfahren nach Abschnitt 7\n\nverfahren Absatz 3 nicht zu einer Entscheidung, wird das HÃ¶chsteinleiten preisverfahren eingeleitet.\n\nKonflikt- (2) Das HÃ¶chstpreisverfahren bezieht sich auf die gesamte\n\nabschnitt Trasse, die den konfliktbehafteten Abschnitt beinhaltet.\n\nFrist, (3) Die DB InfraGO AG fordert die betroffenen EVU/ZB auf,\n\nEntgelthÃ¶he innerhalb von 5 Werktagen ein Entgelt fÃ¼r die gesamte\n\nTrasse anzubieten. Dieses Entgelt muss Ã¼ber dem Entgelt\n\nliegen, das gemÃ¤ÃŸ der gÃ¼ltigen Trassenpreisliste bezogen\n\nauf die gesamte Netzfahrplanperiode zu zahlen wÃ¤re.\n\nGrundlage fÃ¼r die Start-Gebote im HÃ¶chstpreisverfahren\n\nbilden dabei die Entgelte gemÃ¤ÃŸ Anlage 4.2.1.10 der INB.\n\nGebotsabgabe (4) Das Gebot wird Ã¼ber die BNetzA an die DB InfraGO AG",229,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":12,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","f441c98dd5ca03b3c54bb93944e47dfe30a43a5c89153955a4b62195f078e6fe"],["chunk_501cbbfcc60ed496632f8263","wiki/sources/ril-402-0203-inb-2027-data.md",21,"Seite 12","Ã¼ber die BNetzA gesendet.\n\nZuweisung, (5) Die Zuweisung der Trasse erfolgt durch die DB InfraGO AG\n\nDokumentation an den Bieter, der bereit ist, das hÃ¶chste Entgelt zu zahlen.\n\nDie Entscheidung wird dokumentiert und vom EVU/ZB und\n\nder DB InfraGO AG unterzeichnet.\n\nGÃ¼ltig ab 13.12.2026",44,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":12,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","234e1cba88384ddea6dcf5508534ff36a91ef1c7481e56f284fc5028e7e0aa7f"],["chunk_4612b891ff86f24bed892da6","wiki/sources/ril-402-0203-inb-2027-data.md",22,"Seite 13","Bahnbetrieb Trassenmanagement\n\nPlanungsprocedere; 402.0203\n\nAufgaben und AblÃ¤ufe im Planungsprocedere fÃ¼r den Seite 13\n\nNetzfahrplan\n\n9 VorlÃ¤ufiger Netzfahrplanentwurf\n\n(1) Aus dem erfolgreichen Abschluss der Trassenkonstruktion Zeitpunkt\n\nergibt sich der vorlÃ¤ufige Netzfahrplanentwurf. Der Zeitpunkt fÃ¼r die Fertigstellung wird jÃ¤hrlich konkret festgelegt.\n\n(2) Nach Erstellung des vorlÃ¤ufigen Netzfahrplanentwurfs Ãœbergabe beabÃ¼bermittelt die DB InfraGO AG dem ZB oder dem einbezo- sichtigter Trasgenen EVU schriftlich oder elektronisch Ã¼ber TPN bzw. senangebote\n\nPCS den aktuellen Bearbeitungsstand zu ihren jeweiligen\n\nTrassenanmeldungen. ZusÃ¤tzlich stellt die DB InfraGO AG\n\nsÃ¤mtliche angebotenen Trassen allen Dritten, die zu etwaigen Auswirkungen des Netzfahrplans auf ihre MÃ¶glichkeiten zur Inanspruchnahme von Eisenbahnverkehrsdiensten\n\nin der betreffenden Netzfahrplanperiode Stellung nehmen\n\nmÃ¶chten, zur kapazitiven Einsicht in Form der webbasierten Anwendung â€žVNP-Viewerâ€œ zur VerfÃ¼gung. Der Zugang\n\nzum VNP-Viewer erfolgt Ã¼ber den Link\n\nhttps://kundeninfo-fahrplan.de/vnp2026, der fÃ¼r den\n\nZeitraum der Stellungnahme gemÃ¤ÃŸ Ziffer 4.2.1.3 INB freigeschaltet wird.\n\n(3) Dem ZB oder dem einbezogenen EVU, die im Netzfahrplan Stellungnahmen\n\nSchienenwegkapazitÃ¤t nachgefragt haben, wird einen Mo- der EVU/ZB\n\nnat Gelegenheit gegeben, zu dem vorlÃ¤ufigen Netzfahrplanentwurf elektronisch Ã¼ber TPN bzw. PCS Stellung zu\n\nnehmen.\n\nSchriftliche Stellungnahmen sind nur zulÃ¤ssig, sofern der\n\nZB oder das einbezogene EVU sich darauf bezieht, dass\n\nseine Trassenanmeldung unberechtigt nicht im Netzfahrplan berÃ¼cksichtigt wurde. Insbesondere im Fall des technischen Ausfalls bzw. im Fall von ÃœbertragungsstÃ¶rungen\n\ndes Systems TPN oder im Fall eines nicht verfÃ¼gbaren IT-",216,"{\"canonical_url\":null,\"normalized_sha256\":\"51232b4d22620dd47d51e29d3e3d1aaf2ce37fa8cf335b3c47ffd40a068dd347\",\"page\":13,\"source_id\":\"src_f9a635c5153873093579\",\"source_sha256\":\"358d8c5bccb77dd787c817b9b8b5204f7a77ce7af4b8fab509a288c7b7bc19e3\",\"source_version_id\":\"sv_c21c78fd392e9a26efd5d37b\"}","1c2aecd67a7d6f